def edit_distance(a,b)
  m=a.length;n=b.length
  dp=Array.new(m+1){|i| Array.new(n+1,0)}
  (0..m).each{|i| dp[i][0]=i}
  (0..n).each{|j| dp[0][j]=j}
  (1..m).each do |i|
    (1..n).each do |j|
      cost=a[i-1]==b[j-1] ? 0 : 1
      dp[i][j]=[dp[i-1][j]+1,dp[i][j-1]+1,dp[i-1][j-1]+cost].min
    end
  end
  dp[m][n]
end

def coin_change(coins,amount)
  inf=amount+1
  dp=Array.new(amount+1,inf);dp[0]=0
  (1..amount).each{|a| coins.each{|c| dp[a]=[dp[a],dp[a-c]+1].min if c<=a}}
  dp[amount]>amount ? -1 : dp[amount]
end

def rotate_matrix(m)
  m.transpose.map(&:reverse)
end

def topo_sort(n,edges)
  indeg=Array.new(n,0);adj=Array.new(n){[]}
  edges.each{|a,b| adj[a]<<b;indeg[b]+=1}
  q=(0...n).select{|i| indeg[i]==0}.sort
  order=[]
  until q.empty?
    q.sort!;u=q.shift;order<<u
    adj[u].each{|v| indeg[v]-=1;q<<v if indeg[v]==0}
  end
  order.length==n ? order : []
end

def dijkstra(n,edges,src)
  adj=Array.new(n){[]};edges.each{|u,v,w| adj[u]<<[v,w]}
  inf=Float::INFINITY;dist=Array.new(n,inf);dist[src]=0
  pq=[[0,src]]
  until pq.empty?
    pq.sort_by!{|x| x[0]};d,u=pq.shift
    next if d>dist[u]
    adj[u].each{|v,w| (dist[v]=dist[u]+w;pq<<[dist[v],v]) if dist[u]+w<dist[v]}
  end
  dist.map{|x| x==inf ? -1 : x}
end

def kth_largest(a,k)
