def gray_code(n)
  (0...(1<<n)).map{|i| i ^ (i>>1)}
end

def memoize(fn)
  cache={}
  ->(*args){ cache.key?(args) ? cache[args] : (cache[args]=fn.call(*args)) }
end

def deep_dup(o)
  case o
  when Array then o.map{|e| deep_dup(e)}
  when Hash then o.each_with_object({}){|(k,v),h| h[deep_dup(k)]=deep_dup(v)}
  else (o.dup rescue o)
  end
end

def pack(a)
  a.chunk_while{|x,y| x==y}.map{|r| [r.first,r.length]}
end

class Trie
  def initialize
    @root={}
    @count={}
  end
  def insert(word)
    node=@root
    prefix=""
    word.each_char do |ch|
      prefix+=ch
      node[ch]||={}
      @count[prefix]=(@count[prefix]||0)+1
      node=node[ch]
    end
  end
  def count_prefix(prefix)
    @count[prefix]||0
  end
end

def anagram_groups(words)
  groups=Hash.new{|h,k| h[k]=[]}
  words.each{|w| groups[w.chars.sort.join]<<w}
  groups.keys.sort.map{|k| groups[k].sort}
end

class MinStack
  def initialize
    @stack=[]
    @mins=[]
  end
  def push(x)
    @stack<<x
    if @mins.empty? || x<=@mins.last
      @mins<<x
    else
      @mins<<@mins.last
    end
  end
  def pop
    @mins.pop
    @stack.pop
  end
  def top
    @stack.last
  end
  def get_min
    @mins.last
  end
end

class CircularBuffer
  def initialize(size)
    @size=size
    @data=[]
  end
  def push(x)
    @data<<x
    @data.shift if @data.length>@size
  end
  def to_a
    @data.dup
  end
end

